const CHAVE_CADASTRO="cadastroImpulsionar";export function salvarCadastro(r){try{return localStorage.setItem(CHAVE_CADASTRO,JSON.stringify(r)),!0}catch(r){return console.error("Não foi possível salvar os dados no navegador:",r),!1}}export function recuperarCadastro(){try{const r=localStorage.getItem(CHAVE_CADASTRO);return r?JSON.parse(r):null}catch(r){return console.error("Não foi possível recuperar os dados salvos:",r),null}}